<script setup>
import {ref,onMounted,computed,inject} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get,api} from '../api/client';import StatusBadge from '../components/StatusBadge.vue';import EvidenceViewer from '../components/EvidenceViewer.vue';import CursorPager from '../components/CursorPager.vue';import {Check,ArrowRight,ShieldCheck,FileText,Code2} from 'lucide-vue-next';const route=useRoute(),router=useRouter(),user=inject('user');const data=ref({items:[]}),p=ref(null),tag=ref(''),error=ref(''),busy=ref(false),filter=ref(''),reason=ref(''),editor=ref(false),json=ref(''),message=ref('');const canReview=computed(()=>user.value.roles.some(x=>['admin','reviewer'].includes(x)));const evidence=computed(()=>[...new Set((p.value?.changes||[]).flatMap(c=>c.field_evidence.flatMap(f=>f.evidence_ids)))]);const kinds={set_price:'단가 변경',set_availability:'공급 상태 변경',set_product_status:'제품 상태 변경',set_substitution:'대체품 연결',create_product:'신규 제품',create_variant:'신규 규격',create_supplier_item:'공급 품목 등록'};const statusLabels={temporarily_unavailable:'공급 일시중단',supply_ended:'공급 종료',available:'공급 가능',discontinued:'제품 단종',active:'정상'};async function load(cursor=''){error.value='';try{if(route.params.id){const r=await api('/proposals/'+route.params.id);p.value=r.data;if(p.value.analysis_run_id&&!route.query.advanced){try{const report=await get('/analysis-runs/'+p.value.analysis_run_id+'/report');router.replace('/analysis-runs/'+(report.latest_analysis_run_id||p.value.analysis_run_id)+'/review');return}catch{}}tag.value=r.etag;json.value=JSON.stringify(p.value.changes,null,2)}else data.value=await get('/proposals?status='+filter.value+(cursor?'&cursor='+cursor:''))}catch(e){error.value=e.message}}onMounted(()=>load());async function command(action,body={}){busy.value=true;error.value='';try{const r=await api('/proposals/'+p.value.summary.id+'/'+action,{method:'POST',etag:tag.value,body});if(action==='applications')router.push('/jobs/'+r.data.job.id);else{message.value='변경 내용을 저장했습니다.';await load()}}catch(e){error.value=e.message;if(e.status===412)await load()}finally{busy.value=false}}async function decide(action){if(action!=='approve'&&!reason.value.trim()){error.value='보류·반려에는 사유가 필요합니다.';return}await command('decisions',{action,revision:p.value.summary.revision,reason:reason.value})}async function save(){busy.value=true;try{await api('/proposals/'+p.value.summary.id,{method:'PATCH',etag:tag.value,body:{changes:JSON.parse(json.value),edit_reason:reason.value||'검토자가 원문과 비교해 수정'}});editor.value=false;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
</script><template><div class="page-heading"><div><div class="eyebrow">HUMAN REVIEW</div><h1>{{p?'변경안 검토':'변경안 검토함'}}</h1><p class="muted">원문과 변경 내용을 나란히 확인하고, 반영 여부를 결정하세요.</p></div><RouterLink v-if="p" to="/reviews" class="secondary">검토함으로</RouterLink></div><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><template v-if="p"><div class="review-summary"><div class="row"><StatusBadge :value="p.summary.status"/><span class="muted small">내용 v{{p.summary.revision}} · {{p.changes.length}}개 변경</span></div><h2>{{p.summary.title}}</h2><div class="row"><RouterLink v-for="id in p.summary.source_document_ids" :to="'/documents/'+id" class="small"><FileText :size="14"/> 원문 문서 보기 ↗</RouterLink></div></div><div v-if="p.analysis_run_id" class="notice"><RouterLink :to="'/analysis-runs/'+p.analysis_run_id+'/review'" class="primary">품목별 원문 대조·수정 화면으로 →</RouterLink><p class="small">내부 작업 목록 대신 식품 정보와 원문을 나란히 검토할 수 있습니다.</p></div><div v-if="p.issues.length" class="warning"><b>승인 전에 확인해 주세요</b><p v-for="issue in p.issues">{{issue.message}}</p></div><section v-if="canReview&&p.issues.some(i=>i.code==='AI_CONFIRMATION_REQUIRED')" class="panel"><h3>AI가 작성한 내용에서 추정한 부분을 확인해 주세요</h3><p class="muted">위 확인 사항과 오른쪽 원문을 대조한 뒤 기록해 주세요. 확인 후에도 승인과 장부 반영은 따로 진행됩니다.</p><div class="row wrap"><input v-model="reason" placeholder="확인한 공급처·판매 단위·적용일 등" aria-label="AI 추정 항목 확인 사유"><button class="primary" :disabled="busy||!reason.trim()" @click="command('confirm-ai',{revision:p.summary.revision,reason})">원문 대조 확인 완료</button></div></section><div class="review-grid"><section><article v-for="(ch,index) in p.changes" :key="ch.id" class="change-card"><div class="row between"><span class="eyebrow">CHANGE {{String(index+1).padStart(2,'0')}}</span><span class="small muted">{{kinds[ch.operation.kind]}}</span></div><h3>{{statusLabels[ch.operation.status]||ch.operation.name||kinds[ch.operation.kind]}}</h3><div v-if="ch.operation.period" class="diff-box"><div><small>적용 시작일</small><strong>{{ch.operation.period.effective_from}}</strong></div><ArrowRight :size="18"/><div><small>적용 종료일</small><strong>{{ch.operation.period.effective_to||'별도 안내 전까지'}}</strong></div></div><div v-if="ch.operation.value" class="price-diff">{{Number(ch.operation.value.amount).toLocaleString()}}원 <small>/ {{ch.operation.value.quantity}}{{ch.operation.value.unit}} · {{ch.operation.value.tax==='unknown'?'세금 미확인':ch.operation.value.tax}}</small></div><div v-if="ch.operation.reason" class="reason"><small>변경 사유</small><p>{{ch.operation.reason.original_text||'원문에 사유 없음'}}</p></div><div v-if="ch.operation.spec_original" class="notice">규격 {{ch.operation.spec_original}}</div><details><summary>대상·구조·필드별 근거 확인</summary><pre>{{JSON.stringify(ch,null,2)}}</pre></details></article><button v-if="canReview&&p.summary.allowed_actions.includes('edit')" class="secondary" @click="editor=!editor"><Code2 :size="16"/> 변경안 수정</button><div v-if="editor" class="panel editor"><p class="small muted">정확한 상품·규격을 연결하고, 수정한 필드에 근거와 사유를 남기세요.</p><textarea v-model="json" rows="24" aria-label="변경안 JSON"></textarea><input v-model="reason" placeholder="수정 사유" aria-label="수정 사유"><button class="primary" @click="save" :disabled="busy">수정 저장·검증</button></div></section><EvidenceViewer :ids="evidence"/></div><section v-if="canReview" class="decision-panel"><div><ShieldCheck :size="22"/><h3>검토 결과를 선택하세요</h3><p class="small muted">승인 후 ‘장부에 반영’을 실행해야 정보가 변경됩니다.</p></div><input v-model="reason" placeholder="검토 사유 (보류·반려·철회 시 필수)" aria-label="검토 사유"><div class="row wrap"><button v-if="p.summary.allowed_actions.includes('hold')" class="secondary" :disabled="busy" @click="decide('hold')">보류</button><button v-if="p.summary.allowed_actions.includes('reject')" class="danger-outline" :disabled="busy" @click="decide('reject')">반려</button><button v-if="p.summary.allowed_actions.includes('validate')" class="secondary" :disabled="busy" @click="command('validate')">재검증</button><button v-if="p.summary.allowed_actions.includes('approve')" class="primary" :disabled="busy" @click="decide('approve')"><Check :size="16"/> 변경안 승인</button><button v-if="p.summary.allowed_actions.includes('withdraw_approval')" class="secondary" :disabled="busy||!reason.trim()" @click="command('withdraw-approval',{reason})">승인 철회</button><button v-if="p.summary.allowed_actions.includes('apply')" class="primary" :disabled="busy" @click="command('applications',{approved_revision:p.summary.approved_revision})">장부에 반영 <ArrowRight :size="16"/></button></div></section><section v-if="p.decisions.length" class="panel decisions"><h3>검토 기록</h3><p v-for="d in p.decisions"><b>{{{approve:'승인',reject:'반려',hold:'보류'}[d.action]}}</b> · {{d.actor.display_name}} · 내용 v{{d.revision}} <span class="muted">{{d.reason}}</span></p></section></template><section v-else class="panel"><div class="toolbar"><div class="tabs"><button :class="{active:filter===''}" @click="filter='';load()">전체</button><button v-for="[v,l] in [['ready','검토 대기'],['approved','승인 완료'],['on_hold','보류'],['applied','반영 완료']]" :class="{active:filter===v}" @click="filter=v;load()">{{l}}</button></div></div><div class="table-scroll"><table><thead><tr><th>변경안</th><th>상태</th><th>변경 항목</th><th>확인 필요</th><th>등록일</th></tr></thead><tbody><tr class="clickable" v-for="r in data.items" @click="router.push('/reviews/'+r.summary.id)"><td><b>{{r.summary.title}}</b></td><td><StatusBadge :value="r.summary.status"/></td><td>{{r.summary.change_count}}개</td><td>{{r.summary.blocking_count}}개</td><td class="muted">{{new Date(r.summary.created_at).toLocaleDateString('ko-KR')}}</td></tr></tbody></table></div><div v-if="!data.items.length" class="empty">이 상태의 변경안이 없습니다.</div><CursorPager :next="data.next_cursor" @next="load"/></section></template>
